// Generated from public/brand-logos/*.svg: monochrome silhouettes for the
// README badge (docs/badge.md §5.2). Only geometry is kept (no fills, strokes,
// gradients or ids), so a mark inherits the badge palette and can never carry
// an external reference into the SVG. Regenerate after swapping a logo: paths
// stay in their source viewBox and are scaled at render time.

export interface BadgeMark {
  /** [minX, minY, width, height] of the source viewBox. */
  viewBox: [number, number, number, number];
  /** Geometry-only SVG elements, painted by the caller. */
  shapes: string[];
}

